import*as THREE from'three';import{materials}from'../../core/index.js';import{addCadParts}from'../../modeling/cad.js';import{mesh,slab,screw}from'../../modeling/parts.js';import{grove}from'./connectors.js';import{addStickers}from'./stickers.js';import data from'./geometry-data.js';
const tau=Math.PI*2;
function bore(s,x,y,r){const p=new THREE.Path();p.absarc(x,y,r,0,tau,false);s.holes.push(p);}
function extrude(parent,s,d,p,m,n){return mesh(parent,new THREE.ExtrudeGeometry(s,{depth:d,bevelEnabled:false,curveSegments:48}),m,p,n);}
function board(host){
 const s=new THREE.Shape(),x=10.5,y=-12,r=3.8,dx=x-8,dy=Math.sqrt(r*r-dx*dx),a=Math.acos(dx/r);
 s.moveTo(-5.45,-22.2);s.lineTo(-7.4,-22.2);s.lineTo(-x,-19.1);s.lineTo(-x,y-dy);s.absarc(-8,y,r,Math.PI+a,Math.PI-a,false);s.lineTo(-x,15.1);s.lineTo(-9,16.6);s.lineTo(9,16.6);s.lineTo(x,15.1);s.lineTo(x,y+dy);s.absarc(8,y,r,a,tau-a,false);s.lineTo(x,-19.1);s.lineTo(7.4,-22.2);s.lineTo(5.45,-22.2);s.lineTo(5.45,-17.2);s.lineTo(-5.45,-17.2);s.closePath();bore(s,0,y,2.8);
 const black=materials.plastic(0x131615,{roughness:.86}),metal=materials.metal(0xbcbdb4,{roughness:.45}),dark=materials.plastic(0x202321,{roughness:.8}),ceramic=materials.plastic(0xa6a183,{roughness:.8});
 const pcb=extrude(host.body,s,.8,[0,0,-1.7],black,'UWB real black carrier PCB with native mounting scallops,central retaining bore and Grove notch');pcb.userData={role:'physical-pcb',inferred:true};
 const moduleBoard=slab(host.body,17.6,19.8,.7,.15,[0,6.3,-.75],black,[],.02);moduleBoard.name='UWB fixed Ai-Thinker BU01 module PCB';
 const antennaBoard=slab(host.body,13.5,7.2,.7,.08,[0,19.7,-.75],black,[],.01);antennaBoard.name='UWB BU01 integrated fixed antenna PCB extension';
 const copper=new THREE.Shape();copper.moveTo(-6.15,-2.95);copper.quadraticCurveTo(-6.15,-3.2,-5.8,-3.2);copper.lineTo(5.8,-3.2);copper.quadraticCurveTo(6.15,-3.2,6.15,-2.95);copper.lineTo(6.15,3.1);copper.lineTo(-6.15,3.1);copper.closePath();const aperture=new THREE.Path();aperture.moveTo(-4.8,.5);aperture.lineTo(4.8,.5);aperture.lineTo(4.8,-.3);aperture.quadraticCurveTo(4.8,-2.1,0,-2.1);aperture.quadraticCurveTo(-4.8,-2.1,-4.8,-.3);aperture.closePath();copper.holes.push(aperture);
 const antennaCopper=extrude(host.body,copper,.035,[0,19.7,-.045],materials.metal(0xc4a05c,{roughness:.42}),'UWB BU01 integrated planar copper U antenna,non-emissive');antennaCopper.userData={role:'fixed-integrated-antenna',scope:'Own U100 board photo silhouette only;no external socket or RF simulation'};
 const stm32=slab(host.body,7.1,7.1,1.35,.18,[0,6.4,0],dark,[],.02);stm32.name='UWB real STM32F103C8T6 fixed LQFP48 package';const leads=[];for(const sign of[-1,1])for(let i=0;i<12;i++){leads.push(mesh(host.body,new THREE.BoxGeometry(.27,1.1,.2),metal,[(i-5.5)*.5,6.4+sign*3.9,.28],'UWB STM32 LQFP48 north-south gull-wing lead'));leads.push(mesh(host.body,new THREE.BoxGeometry(1.1,.27,.2),metal,[sign*3.9,6.4+(i-5.5)*.5,.28],'UWB STM32 LQFP48 east-west gull-wing lead'));}
 const pads=[];for(const side of[-1,1])for(let i=0;i<6;i++){const pad=slab(host.body,1.6,1.25,.13,.13,[side*9,13.2-i*2.54,-.7],metal,[],.01);pad.name='UWB BU01 module fixed side castellated solder pad';pads.push(pad);}
 for(let i=0;i<5;i++){const pad=slab(host.body,1.5,1.2,.1,.1,[(i-2)*2.54,15.1,.02],metal,[],.01);pad.name='UWB BU01 fixed upper programming solder pad';pads.push(pad);}
 const crystal=slab(host.body,3.2,2.5,.65,.25,[0,-.7,0],metal,[],.02);crystal.name='UWB real metal crystal can';
 const regulator=slab(host.body,3.2,2.8,.75,.18,[-.6,-4.3,-.9],dark,[],.03);regulator.name='UWB carrier fixed SY8089 regulator package';
 const dw1000=slab(host.body,6.1,6.1,.65,.18,[0,7.2,-2.5],dark,[],.02);dw1000.name='UWB BU01 concealed fixed DW1000 package envelope';dw1000.userData={role:'concealed-package',inferred:true,scope:'Module constituent appearance envelope,exact rear layout unconfirmed'};
 const passives=[];for(const[px,py,w,h,d]of[[-4.8,-.3,1.7,.8,.5],[4.5,10.8,.8,1.6,.45],[-2.4,12.2,1.5,.9,.5],[4.9,3.3,.9,1.6,.5],[3.8,-4.9,1.8,1.0,.65],[-3.8,-1.5,1.4,.8,.5],[-6.3,-18.1,1.1,2.4,.65]]){const q=slab(host.body,w,h,d,.08,[px,py,py>-3?0:-.9],py===-4.9?ceramic:dark,[],.01);q.name='UWB fixed board decoupling or resistor package';passives.push(q);for(const side of[-1,1])mesh(host.body,new THREE.BoxGeometry(.2,h,.12),metal,[px+side*(w/2-.1),py,py>-3?.1:-.8],'UWB fixed passive solder end');}
 return{pcb,moduleBoard,antennaBoard,antennaCopper,stm32,leads,pads,crystal,regulator,dw1000,passives};
}
export function buildUWB(host){const parts=addCadParts(host,data,{shell:materials.plastic(0xe8e9e3,{roughness:.79})}),pcb=board(host),input=grove(host),fixing=screw(host.body,[0,-12,-3.98],'back',1.25);fixing.name='UWB fixed rear retaining hex screw';
 const substrate=materials.plastic(0xd9dadb,{roughness:.85}),frontCarrier=slab(host.body,17.8,27.8,.1,.08,[0,8,3.7],substrate,[],.005),backCarrier=slab(host.body,16,28,.1,.08,[0,8,-3.9],substrate,[],.005);frontCarrier.name='UWB physical front adhesive substrate spanning actual native recess';backCarrier.name='UWB physical rear adhesive substrate on native recess';
 host.uwbAssembly={parts,pcb,input,fixing,frontCarrier,backCarrier};host.unitStickers=addStickers(host);}
